module DoorTransition =

    /// Every legal transition as (from, command, to).
    let legal : (DoorState * DoorCommand * DoorState) list =
        [ DoorState.Closed, DoorCommand.Lock, DoorState.Locked
          DoorState.Closed, DoorCommand.Open, DoorState.Open
          DoorState.Locked, DoorCommand.Unlock, DoorState.Closed
          DoorState.Open, DoorCommand.Close, DoorState.Closed ]

    /// The target of a command, or None where the command is not legal. Every
    /// (state, command) pair is listed; there is no catch-all.
    let target (state: DoorState) (command: DoorCommand) : DoorState option =
        match state, command with
        | DoorState.Closed, DoorCommand.Close -> None
        | DoorState.Closed, DoorCommand.Lock -> Some DoorState.Locked
        | DoorState.Closed, DoorCommand.Open -> Some DoorState.Open
        | DoorState.Closed, DoorCommand.Unlock -> None
        | DoorState.Locked, DoorCommand.Close -> None
        | DoorState.Locked, DoorCommand.Lock -> None
        | DoorState.Locked, DoorCommand.Open -> None
        | DoorState.Locked, DoorCommand.Unlock -> Some DoorState.Closed
        | DoorState.Open, DoorCommand.Close -> Some DoorState.Closed
        | DoorState.Open, DoorCommand.Lock -> None
        | DoorState.Open, DoorCommand.Open -> None
        | DoorState.Open, DoorCommand.Unlock -> None

    /// The guards a legal command must satisfy in a state.
    let guards (state: DoorState) (command: DoorCommand) : DoorGuard list =
        match state, command with
        | DoorState.Closed, DoorCommand.Close -> []
        | DoorState.Closed, DoorCommand.Lock -> [ DoorGuard.KeyPresent ]
        | DoorState.Closed, DoorCommand.Open -> []
        | DoorState.Closed, DoorCommand.Unlock -> []
        | DoorState.Locked, DoorCommand.Close -> []
        | DoorState.Locked, DoorCommand.Lock -> []
        | DoorState.Locked, DoorCommand.Open -> []
        | DoorState.Locked, DoorCommand.Unlock -> [ DoorGuard.KeyPresent ]
        | DoorState.Open, DoorCommand.Close -> []
        | DoorState.Open, DoorCommand.Lock -> []
        | DoorState.Open, DoorCommand.Open -> []
        | DoorState.Open, DoorCommand.Unlock -> []

    /// The invariants that must hold in a state.
    let invariantsIn (state: DoorState) : DoorInvariant list =
        match state with
        | DoorState.Closed -> []
        | DoorState.Locked -> [ DoorInvariant.Latched ]
        | DoorState.Open -> []

    /// Semantic capabilities a command requires. Checked against the held set the
    /// host supplies; this is semantic authority, not authentication.
    let requiredCapabilities (command: DoorCommand) : string list =
        match command with
        | DoorCommand.Close -> []
        | DoorCommand.Lock -> []
        | DoorCommand.Open -> []
        | DoorCommand.Unlock -> [ "door.unlock" ]

    /// Effects an accepted command requests.
    let effects (command: DoorCommand) : DoorEffect list =
        match command with
        | DoorCommand.Close -> []
        | DoorCommand.Lock -> []
        | DoorCommand.Open -> []
        | DoorCommand.Unlock -> [ DoorEffect.Unlock ]

    /// Decides one command. Refusal is data; nothing is applied or performed here.
    let decide (rules: DoorRules) (held: Set<string>) (state: DoorState) (command: DoorCommand) : Result<DoorDecision, DoorRefusal> =
        match target state command with
        | None -> Error(DoorRefusal.InvalidTransition(state, command))
        | Some next ->
